struct Counter {
    count: i32,
}

impl Counter {
    fn new() -> Counter {
        return Counter { count: 0 };
    }

    fn increment(&mut self) {
        self.count = self.count + 1;
    }
}

fn main() {
    let mut c = Counter::new();
    for _ in 0..5 {
        c.increment();
    }
    print(c.count);
} // 5

fn fib(n: i32) -> i32 {
    if n <= 1 {
        return n;
    }
    return fib(n - 1) + fib(n - 2);
}

fn main() {
    print(fib(10));
} // 55

